function summarizeWindow(events, nowMs, windowMs, cap) {
  const seenIds = new Set();
  const deduped = [];

  for (const ev of Array.isArray(events) ? events : []) {
    const id = ev && typeof ev === "object" ? ev.id : undefined;
    if (typeof id === "string" && id.length > 0) {
      if (seenIds.has(id)) continue;
      seenIds.add(id);
    }
    deduped.push(ev);
  }

  const start = nowMs - windowMs;
  const byModelMap = new Map();
  let used = 0;
  let minTs = Infinity;

  for (const ev of deduped) {
    if (!ev || typeof ev !== "object") continue;

    const ts = ev.ts;
    if (typeof ts !== "number" || !Number.isFinite(ts)) continue;
    if (ts < start || ts > nowMs) continue;

    if (ev.provider !== "opencode-go") continue;
    if (ev.error) continue;

    if (typeof ev.model !== "string") continue;
    if (ev.model.toLowerCase().endsWith("-free")) continue;

    used += 1;
    if (ts < minTs) minTs = ts;

    let model = ev.model.toLowerCase();
    while (model.startsWith("opencode-go/")) {
      model = model.slice("opencode-go/".length);
    }

    byModelMap.set(model, (byModelMap.get(model) || 0) + 1);
  }

  const byModel = {};
  for (const key of Array.from(byModelMap.keys()).sort()) {
    byModel[key] = byModelMap.get(key);
  }

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = summarizeWindow;
  module.exports.summarizeWindow = summarizeWindow;
}
